import random

class {{class_name}}:
    def __init__(self, max_level=16, p=0.5):
        self.max_level = max_level
        self.p = p
        self.head = [None]*max_level
        self.level = 0
    def _rand_level(self):
        lvl = 0
        while random.random() < self.p and lvl < self.max_level - 1:
            lvl += 1
        return lvl
    def insert(self, val):
        update = [None]*self.max_level
        node = self.head
        for i in range(self.level, -1, -1):
            while node[i] and node[i][0] < val:
                node = node[i][1]
            update[i] = node
        lvl = self._rand_level()
        if lvl > self.level:
            for i in range(self.level+1, lvl+1):
                update[i] = self.head
            self.level = lvl
        new_node = [val, [None]*(lvl+1)]
        for i in range(lvl+1):
            new_node[1][i] = update[i][i] if update[i] is not self.head else self.head[i]
            if update[i] is self.head:
                self.head[i] = new_node
            else:
                update[i][i] = new_node
